<?php
declare(strict_types=1);
require_once __DIR__.'/../bootstrap.php';
Auth::requireRole('admin');
$pdo=db();
$rows=$pdo->query("SELECT a.id,a.user_id,a.referral_code,a.status,a.created_at,u.name,u.email,COUNT(DISTINCT r.id) referrals,COUNT(DISTINCT CASE WHEN r.status='qualified' THEN r.id END) qualified FROM affiliate_profiles a JOIN users u ON u.id=a.user_id LEFT JOIN affiliate_referrals r ON r.affiliate_id=a.id GROUP BY a.id,a.user_id,a.referral_code,a.status,a.created_at,u.name,u.email ORDER BY a.id DESC")->fetchAll(PDO::FETCH_ASSOC);
$flashError=flash('error');$flashSuccess=flash('success');
if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf($_POST['_csrf']??null); $id=filter_input(INPUT_POST,'affiliate_id',FILTER_VALIDATE_INT);$status=(string)($_POST['status']??''); if(!$id||!in_array($status,['active','suspended'],true)){flash('error','Invalid affiliate update.');redirect('/admin/affiliates.php');} $st=$pdo->prepare('UPDATE affiliate_profiles SET status=? WHERE id=?');$st->execute([$status,$id]);flash('success','Affiliate status updated.');redirect('/admin/affiliates.php'); }
$active='affiliates';$pageTitle='Affiliates';$pageDescription='Manage affiliate accounts and referral activity.';
?><!doctype html><html lang="en"><head><link rel="icon" href="<?= e(url('/assets/images/favicon-32.png')) ?>"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Affiliates · DogoFlow Admin</title><link rel="stylesheet" href="<?=url('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=url('/assets/css/admin.css')?>"><style>.aff-table-wrap{overflow:auto;background:#fff;border:1px solid #e2e8f0;border-radius:14px}.aff-table{width:100%;border-collapse:collapse;min-width:760px}.aff-table th,.aff-table td{padding:13px 15px;text-align:left;border-bottom:1px solid #edf1f5}.aff-table th{font-size:.78rem;color:#64748b;background:#f8fafc}.aff-table form{display:flex;gap:6px}.aff-table select,.aff-table button{padding:7px;border:1px solid #dbe3ee;border-radius:8px;background:white}.aff-table button{background:#00a3ff;color:white;border:0;font-weight:700}.notice{padding:12px 15px;border-radius:10px;margin:12px 0;background:#ecfdf5;color:#065f46}</style></head><body class="admin-shell"><?php require __DIR__.'/../partials/admin_sidebar.php';?><section class="admin-main"><?php require __DIR__.'/../partials/admin_topbar.php';?><main class="admin-content"><div class="page-heading"><div><h1>Affiliates</h1><p>Manage affiliate accounts and referral activity.</p></div></div><?php if($flashError):?><div class="notice" style="background:#fff1f2;color:#9f1239"><?=e($flashError)?></div><?php endif;?><?php if($flashSuccess):?><div class="notice"><?=e($flashSuccess)?></div><?php endif;?><div class="aff-table-wrap"><table class="aff-table"><thead><tr><th>Affiliate</th><th>Referral code</th><th>Referrals</th><th>Approved sellers</th><th>Status</th><th>Joined</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><br><small><?=e($r['email'])?></small></td><td><?=e($r['referral_code'])?></td><td><?= (int)$r['referrals']?></td><td><?= (int)$r['qualified']?></td><td><?=e(ucfirst($r['status']))?></td><td><?=e($r['created_at'])?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="affiliate_id" value="<?=(int)$r['id']?>"><select name="status"><option value="active" <?=$r['status']==='active'?'selected':''?>>Active</option><option value="suspended" <?=$r['status']==='suspended'?'selected':''?>>Suspended</option></select><button type="submit">Save</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No affiliate accounts yet. Affiliate registrations will appear here.</td></tr><?php endif;?></tbody></table></div></main></section></body></html>